package mx.com.mesaregia.reportes.integration.client; import mx.com.mesaregia.reportes.domain.model.*; import mx.com.mesaregia.reportes.integration.port.CotizacionesReportSourcePort; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.time.LocalDate; import java.util.*; import static mx.com.mesaregia.reportes.integration.client.ReportAdapterSupport.*;
@Component public class CotizacionesReportRestAdapter implements CotizacionesReportSourcePort {private final RestClient client;public CotizacionesReportRestAdapter(InternalRestClientFactory f){client=f.create(System.getenv().getOrDefault("MR_COTIZACIONES_BASE_URL","http://localhost:8086"));}@Override public FuenteReporteData consultar(ReporteCriterios c){var rows=load(c,null);return new FuenteReporteData("mr-cotizaciones-service",cols(),rows);}List<Map<String,Object>> load(ReporteCriterios c,String estado){var rows=new ArrayList<Map<String,Object>>();int p=0,total;do{int page=p;var r=client.get().uri(u->{var b=u.path("/internal/v1/cotizaciones").queryParam("page",page).queryParam("size",200);if(estado!=null)b.queryParam("estado",estado);if(c.fechaInicio()!=null)b.queryParam("desde",c.fechaInicio());if(c.fechaFin()!=null)b.queryParam("hasta",c.fechaFin());return b.build();}).retrieve().body(PageDto.class);if(r==null)break;for(var x:r.content())rows.add(row("id",x.id(),"folio",x.folio(),"idCliente",x.idClienteProspecto(),"estado",x.estado(),"fechaEvento",x.fechaEvento(),"versionElegida",x.idVersionElegida()));total=r.totalPages();p++;}while(p<total);return rows;}private List<ReporteColumna> cols(){return List.of(c("id","ID"),c("folio","Folio"),c("idCliente","Cliente"),c("estado","Estado"),c("fechaEvento","Fecha evento"),c("versionElegida","Versión elegida"));}private record Cot(Long id,String folio,Long idClienteProspecto,String estado,LocalDate fechaEvento,Long idVersionElegida){}private record PageDto(List<Cot> content,int totalPages){}
}
